// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address initialMigrator = address(0xdead);

    function setUp() public { 
        c = new C(address(this), address(this));
        c.setMigrator(initialMigrator);
    }

    function testFuzz_property(address newMigrator, address rewardToken) public {
        // Remove the initial migrator from possible values
        vm.assume(newMigrator != initialMigrator);

        // Call various public functions that could affect state
        c.setMigrator(newMigrator);

        // The critical call: addReward should never change migrator
        c.addReward(rewardToken);

        // After all these calls, migrator must still be newMigrator (not reset to zero)
        assertTrue(c.migrator() == newMigrator);
    }
}

